function global:L([string]$s) {
    if ($global:NeonLang -eq 'ca' -or -not $s) { return $s }
    $e = $global:NeonI18n[$s]
    if (-not $e) { return $s }
    $r = $e[$(if ($global:NeonLang -eq 'es') { 0 } else { 1 })]
    # keys are case-insensitive: the original text's initial case is kept ("Estat" → "Status")
    if ($s.Length -and [char]::IsUpper($s[0]) -and $r.Length -and [char]::IsLower($r[0])) { $r = [char]::ToUpper($r[0]) + $r.Substring(1) }
    return $r
}
